<script lang="ts">
 import { page } from '$app/state';
 import { onMount } from 'svelte';
 import { invalidateAll } from '$app/navigation';
 import { Phone, Search, ExternalLink, NotebookPen, ArrowLeft, UserRound, RefreshCw } from 'lucide-svelte';
 import CareerRejectionReview from '$lib/components/chat/CareerRejectionReview.svelte';
 import type { PageData } from './$types.js';
 let {data}:{data:PageData}=$props();
 $effect(()=>{const identity=page.url.searchParams.get('position');if(identity){selectedId=identity;filter='all';mobileDetail=true;}});
 let query=$state(''),filter=$state('open'),sort=$state('recent'),selectedId=$state<string|null>(null),call=$state(false),mobileDetail=$state(false);
 let noteOpen=$state(false),draft=$state(''),noteRevision=$state(0),saving=$state(false),notice=$state(''),refreshing=$state(false),root:HTMLElement;
 const normalize=(value:string)=>value.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const counts=$derived({open:data.rows.filter(r=>r.status==='open').length,pending:data.rows.filter(r=>r.status==='pending').length,rejected:data.rows.filter(r=>r.status==='rejected').length,all:data.rows.length});
 const filtered=$derived(data.rows.filter(r=>(call||filter==='all'||r.status===filter)&&normalize([r.employer,r.role,r.location,...r.contacts.map(c=>c.name+' '+(c.phone??''))].join(' ')).includes(normalize(query)))
  .sort((a,b)=>sort==='company'?a.employer.localeCompare(b.employer):sort==='oldest'?(a.date??'9999').localeCompare(b.date??'9999'):(b.date??'').localeCompare(a.date??'')));
 const selected=$derived(filtered.find(r=>r.id===selectedId)??filtered[0]);
 const ceiling=$derived(Math.max(4,Math.ceil(Math.max(...data.weeks.map(w=>Math.max(w.applications,w.rejections)))/4)*4));
 const statusLabel=(status:string)=>status==='rejected'?'Absage erhalten':status==='pending'?'Absage-Zuordnung offen':'Rückmeldung offen';
 const date=(value:string|null)=>value?new Intl.DateTimeFormat('de-CH',{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(value+'T12:00:00Z')):'Datum nicht dokumentiert';
 const waited=(value:string|null)=>{if(!value)return 'Datum offen';const days=Math.floor((Date.parse(data.asOf)-Date.parse(value+'T00:00:00+02:00'))/86400000);return days===0?'Heute':days===1?'Seit gestern':`${days} Tage`;};
 const timestamp=(value:string)=>new Date(value).toLocaleString('de-CH',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
 function select(id:string){selectedId=id;mobileDetail=true;noteOpen=false;notice='';if(window.innerWidth<=640)root.scrollIntoView({block:'start'});}
 function openNote(){if(!selected)return;const note=data.notes[selected.id];draft=note?.text??'';noteRevision=note?.revision??0;noteOpen=true;notice='';}
 async function saveNote(){
  if(!selected)return;saving=true;notice='';
  try{const response=await fetch('/api/career/application-note',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identity:selected.id,text:draft,revision:noteRevision})});const result=await response.json();if(!response.ok)throw Error(result.message);noteRevision=result.revision;noteOpen=false;await invalidateAll();notice='Gesprächsnotiz in Folio gespeichert.';}
  catch(e){notice=e instanceof Error?e.message:'Notiz konnte nicht gespeichert werden.';}finally{saving=false;}
 }
 async function refresh(){refreshing=true;try{await invalidateAll();}finally{refreshing=false;}}
 onMount(()=>{const timer=setInterval(()=>{if(!noteOpen&&!saving&&!document.hidden)void refresh();},30_000);return()=>clearInterval(timer);});
</script>

<svelte:head><title>Bewerbungen · Folio</title></svelte:head>
{#if data.historicalRejection}<aside class="border border-border rounded-xl bg-card m-4 p-4" aria-label="Verknüpfte Absage"><b>{data.historicalRejection.employer}</b><p>{data.historicalRejection.title}</p><p class="text-muted-foreground">Absage erfasst · {data.historicalRejection.date}</p><p>{data.historicalRejection.reason}</p></aside>{/if}

<div class="career" class:call class:mobile-detail={mobileDetail} bind:this={root}>
 {#if data.sourceStatus && data.sourceStatus!=='ready'}<p role="status" class="notice">{data.sourceStatus==='unconfigured'?'Noch keine Bewerbungsquelle eingerichtet.':data.sourceStatus==='missing'?'Die eingerichtete Bewerbungsquelle ist nicht erreichbar.':'Die Bewerbungsquelle konnte nicht gelesen werden.'} Ein leerer Überblick bedeutet hier nicht, dass keine Bewerbungen offen sind.</p>{/if}

 <header class="heading"><div><h1>Bewerbungen</h1><p>Alles Wichtige, wenn das Telefon klingelt.</p></div><button class="button primary" aria-pressed={call} onclick={()=>{call=!call;mobileDetail=false;}}><Phone size={15}/>{call?'Zur Übersicht':'Anrufansicht'}</button></header>
 <section class="overview" aria-label="Bewerbungen im Zeitverlauf">
  <div class="stats"><div><strong class="number">{counts.open}</strong><p>Antwort offen</p></div><div class="stats-bottom"><div><strong>{counts.all}</strong><small>versandt</small></div><div><strong>{counts.rejected}</strong><small>Absagen</small></div></div></div>
  <div class="plot"><div class="plot-heading"><b>Die letzten 8 Wochen</b><div class="legend"><span><i></i>Bewerbungen</span><span><i class="rose"></i>Absagen</span></div></div>
   <svg viewBox="0 0 600 115" role="img" aria-label="Bewerbungen und erhaltene Absagen je Kalenderwoche">
    <title>Versandte Bewerbungen und bestätigte Absagen</title>
    {#each [0,1,2,3,4] as n}<line x1="25" x2="595" y1={85-n*18} y2={85-n*18}/><text x="19" y={89-n*18} text-anchor="end">{ceiling*n/4}</text>{/each}
    {#each data.weeks as week,i}
     <g><title>Woche ab {week.label}: {week.applications} Bewerbungen, {week.rejections} Absagen</title>
      <rect x={45+i*70} y={85-week.applications/ceiling*72} width="15" height={week.applications/ceiling*72} rx="2"/>
      <rect class="rose" x={63+i*70} y={85-week.rejections/ceiling*72} width="15" height={week.rejections/ceiling*72} rx="2"/>
      <text x={61+i*70} y="108" text-anchor="middle">{week.label}</text>
     </g>
    {/each}
   </svg><small>Versand- und Absagedatum · aktuelle Woche noch offen</small>
  </div>
 </section>
 <div class="controls"><label class="search"><Search size={17}/><input aria-label="Bewerbungen durchsuchen" placeholder="Arbeitgeber, Stelle, Kontakt oder Telefon …" bind:value={query} oninput={()=>{noteOpen=false;notice='';}}/></label><select aria-label="Bewerbungen sortieren" bind:value={sort}><option value="recent">Zuletzt beworben</option><option value="oldest">Längste Wartezeit</option><option value="company">Arbeitgeber A–Z</option></select><button class="button refresh" aria-label="Tracker aktualisieren" disabled={refreshing} onclick={refresh}><RefreshCw size={16}/></button></div>
 <div class="filters">{#each [{key:'open',label:'Antwort offen'},{key:'pending',label:'Zuordnung prüfen'},{key:'rejected',label:'Absagen'},{key:'all',label:'Alle'}] as tab}<button aria-pressed={filter===tab.key} onclick={()=>{filter=tab.key;mobileDetail=false;noteOpen=false;notice='';}}>{tab.label}<span>{counts[tab.key as keyof typeof counts]}</span></button>{/each}</div>
 {#if call&&query}<div class="call-results">{#each filtered as row}<button class="button" onclick={()=>select(row.id)}>{row.employer}</button>{/each}</div>{/if}
 {#if filter==='pending'&&data.sync.report}<div class="review">{#key data.sync.report}<CareerRejectionReview output={data.sync.report}/>{/key}</div>{/if}
 <button class="button mobile-back" onclick={()=>{mobileDetail=false;call=false;root.scrollIntoView({block:'start'});}}><ArrowLeft size={16}/>Zur Übersicht</button>
 <div class="workspace">
  <section class="master" aria-label="Bewerbungsliste"><!-- The scroll region is focusable so keyboard users can scroll the full list. -->
  <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
  <div class="list" tabindex="0" role="region" aria-label="Alle Bewerbungen, fortlaufend scrollbar">
   {#each filtered as row (row.id)}<button class="row" aria-pressed={selected?.id===row.id} onclick={()=>select(row.id)}>
    <span class="row-top"><b>{row.employer}</b><time>{row.date?date(row.date).slice(0,6):'Datum offen'}</time></span><span class="role">{row.role}</span><span class="meta"><span>{row.location} · {row.terms.match(/\d+\s*[-–]\s*\d+\s*%|\d+\s*%/)?.[0]??'Pensum offen'}</span><span>{row.status==='open'?waited(row.date):statusLabel(row.status)}</span></span>
    {#if row.contacts.length}<span class="contact-mark"><UserRound size={12}/>{row.contacts.map(c=>c.name).join(' · ')}</span>{/if}
   </button>{:else}<p class="empty">Keine Bewerbung für diese Auswahl.</p>{/each}
  </div><small class="list-foot">{filtered.length} Bewerbungen · fortlaufende Liste</small></section>
  <article class="detail" aria-label="Gesprächsdetails">
   {#if selected}
    <div class="detail-head"><p class="status" class:rejected={selected.status==='rejected'} class:pending={selected.status==='pending'}>{statusLabel(selected.status)} · beworben {date(selected.date)}</p><p class="company">{selected.employer}</p><h2>{selected.role}</h2><p class="summary">{selected.summary}</p>
     {#if selected.status==='pending'}<p class="attention">Eine Absagemail ist noch nicht eindeutig zugeordnet. Unter „Zuordnung prüfen“ findest du den Beleg.</p>{/if}
     {#if selected.rejection}<small>Absage vom {date(selected.rejection)}</small>{/if}
    </div>
    <section><dl class="facts"><div><dt>Ort & Pensum</dt><dd>{selected.location}<small>{selected.terms}</small></dd></div><div><dt>Homeoffice</dt><dd>{selected.remote}</dd></div><div class="wide"><dt>Eigene Lohnvorstellung</dt><dd>{selected.salary}{#if selected.salary!=='Nicht dokumentiert'}<small>{selected.salaryKind}</small>{/if}</dd></div>{#if selected.availability}<div class="wide"><dt>Verfügbarkeit angegeben</dt><dd>{selected.availability}</dd></div>{/if}</dl></section>
    <section><h3>Ansprechpersonen</h3>{#each selected.contacts as contact}<div class="contact"><span class="avatar">{contact.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span><div><b>{contact.name}</b><small>{contact.role}</small>{#if contact.phone}<a href={'tel:'+contact.phone.replace(/[^+\d]/g,'')}>{contact.phone}</a>{/if}</div></div>{:else}<p class="muted">Noch keine Person dokumentiert.</p>{/each}{#if selected.reference}<p class="reference">{selected.reference}</p>{/if}</section>
    <section><h3>Für das erste Gespräch</h3>{#if selected.talk}<p class="prep">{selected.talk}</p>{/if}<ul class="questions">{#each selected.questions as question}<li>{question}</li>{/each}</ul></section>
    <div class="actions"><a class="button" href={selected.url} target="_blank" rel="noopener noreferrer"><ExternalLink size={15}/>Online-Stelle</a><button class="button" onclick={openNote}><NotebookPen size={15}/>Gesprächsnotiz</button></div>
    {#if noteOpen}<div class="note-form"><label for="conversation-note">Gesprächsnotiz · lokal in Folio</label><textarea id="conversation-note" bind:value={draft} maxlength="8000" placeholder="Wer hat angerufen? Termin, Gesprächspartner, nächste Schritte …"></textarea><button class="button primary" disabled={saving} onclick={saveNote}>{saving?'Speichert …':'Notiz speichern'}</button><button class="button" disabled={saving} onclick={()=>noteOpen=false}>Abbrechen</button></div>
    {:else if data.notes[selected.id]?.text}<div class="saved-note"><h3>Deine Gesprächsnotiz</h3><p>{data.notes[selected.id].text}</p><small>{timestamp(data.notes[selected.id].updatedAt)}</small></div>{/if}
    {#if notice}<p class="notice" role="status">{notice}</p>{/if}
    <details class="evidence"><summary>Verlauf & Quellen{selected.ref?' · '+selected.ref:''}</summary><p><b>{date(selected.date)} · Bewerbung versandt</b><br/>{selected.portal}</p>{#if selected.rejection}<p><b>{date(selected.rejection)} · Absage erhalten</b></p>{/if}<p>{selected.verified?'Quellencheck laut Carta: '+date(selected.verified):'Kein aktueller Online-Check dokumentiert.'} Die Verfügbarkeit der Anzeige wird hier nicht erneut geprüft.</p>{#if selected.briefStale}<p class="attention">Carta wurde geändert. Die bisherige Gesprächszusammenfassung muss aktualisiert werden; hier stehen die aktuellen Originalangaben.</p>{/if}<details><summary>Originalnotiz aus Carta</summary><p class="original-note">{selected.note||'Keine Notiz dokumentiert.'}</p></details></details>
   {:else}<p class="empty">Eine Bewerbung auswählen, um die Gesprächsdetails zu sehen.</p>{/if}
  </article>
 </div>
 <footer><div><a href="/mail-intake">{data.sync.enabled&&data.sync.runtime?'Stündlicher Mail-Abgleich aktiv':'Mail-Abgleich pausiert'}</a>{#if data.sync.checkedAt}<span> · {timestamp(data.sync.checkedAt)}</span>{/if}{#if data.sync.state==='checking'||data.sync.state==='applying'}<span> · wird abgeglichen</span>{/if}{#if data.sync.error}<span class="attention"> · Abgleich unterbrochen, bitte Lauf prüfen</span>{/if}</div><a href="/career/mobile">Neue Stellen & Chancen →</a><small>Carta als gemeinsame Quelle · {data.interestCount} Interessensbekundung · {data.closedCount} geschlossenes Projekt separat</small></footer>
</div>

<style>
 .career{--blue:#49749f;--rose:#bb7182;--soft:color-mix(in srgb,var(--blue) 9%,var(--color-card));max-width:1380px;margin:auto;color:var(--color-foreground);font-size:14px;line-height:1.45}.career *{box-sizing:border-box}h1,h2,h3,p,dl{margin:0}h1{font-size:28px;font-weight:650;letter-spacing:-.7px}h2{font-size:21px;line-height:1.3;font-weight:620}h3{font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:var(--color-muted-foreground);font-weight:650}button,input,select,textarea{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,.list:focus-visible{outline:2px solid var(--blue);outline-offset:3px}small,.muted{color:var(--color-muted-foreground);font-size:12px}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}.heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:2px 0 20px}.heading p{color:var(--color-muted-foreground);font-size:13px;margin-top:4px}.button{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid var(--color-border);border-radius:8px;padding:8px 12px;background:var(--color-card);color:var(--color-foreground);font-size:12px;white-space:nowrap;text-decoration:none}.button:hover{background:var(--soft);text-decoration:none}.primary{background:var(--color-foreground);color:var(--color-background)}.primary:hover{background:var(--blue);color:white}.button:disabled{opacity:.5;cursor:wait}.overview{display:grid;grid-template-columns:190px minmax(0,1fr);background:var(--color-card);border:1px solid var(--color-border);border-radius:12px;margin-bottom:20px}.stats{padding:20px;border-right:1px solid var(--color-border)}.number{font-size:38px;font-weight:600;line-height:1;letter-spacing:-1px}.stats p{font-size:12px;color:var(--color-muted-foreground);margin-top:6px}.stats-bottom{display:flex;gap:30px;border-top:1px solid var(--color-border);margin-top:17px;padding-top:10px}.stats-bottom strong{display:block;font-size:20px;font-weight:600}.plot{padding:16px 22px 10px;min-width:0}.plot-heading{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;font-size:12px}.legend{display:flex;gap:15px;font-size:11px;color:var(--color-muted-foreground)}.legend span{display:flex;align-items:center;gap:5px}.legend i{display:inline-block;width:14px;height:3px;background:var(--blue)}.legend .rose{background:var(--rose)}svg{display:block;width:100%;height:116px}svg line{stroke:var(--color-border);stroke-width:1}svg text{fill:var(--color-muted-foreground);font:11px sans-serif}svg rect{fill:var(--blue)}svg .rose{fill:var(--rose)}.plot>small{font-size:11px}.controls{display:flex;gap:10px;margin-bottom:12px}.search{display:flex;align-items:center;gap:8px;padding:0 11px;border:1px solid var(--color-border);border-radius:8px;flex:1;background:var(--color-card);min-width:0}.search input{border:0;background:transparent;padding:10px 0;min-width:0;width:100%;font-size:13px;color:inherit}.controls select{border:1px solid var(--color-border);border-radius:8px;padding:8px;background:var(--color-card);font-size:12px;color:inherit}.filters{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}.filters button{border:0;border-radius:7px;padding:7px 10px;font-size:12px;color:var(--color-muted-foreground);background:transparent;display:flex;gap:8px}.filters button[aria-pressed=true]{background:var(--color-foreground);color:var(--color-background)}.filters span{opacity:.75}.workspace{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:20px;align-items:start}.master{min-width:0}.list{display:flex;flex-direction:column;gap:8px;max-height:clamp(390px,calc(100dvh - 375px),780px);overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable;padding:1px 7px 4px 1px}.row{flex-shrink:0;width:100%;text-align:left;padding:14px;background:var(--color-card);border:1px solid var(--color-border);border-radius:10px}.row[aria-pressed=true]{border-color:var(--blue);box-shadow:inset 3px 0 var(--blue);background:var(--soft)}.row-top{display:flex;justify-content:space-between;gap:8px;align-items:baseline}.row-top b{font-size:13px;font-weight:650;overflow-wrap:anywhere}.row time{white-space:nowrap;font-size:11px;color:var(--color-muted-foreground)}.role{display:block;font-size:13px;margin:4px 0;line-height:1.4}.meta{display:flex;justify-content:space-between;gap:7px;flex-wrap:wrap;font-size:11px;color:var(--color-muted-foreground)}.contact-mark{display:flex;align-items:center;gap:5px;color:var(--blue);font-size:11px;margin-top:7px}.list-foot{display:block;margin:10px 0 0;font-size:11px}.detail{background:var(--color-card);border:1px solid var(--color-border);border-radius:12px;min-width:0;overflow:hidden;max-height:clamp(440px,calc(100dvh - 340px),960px);overflow-y:auto;overscroll-behavior:contain}.detail-head{padding:20px;border-bottom:1px solid var(--color-border)}.status{font-size:11px;color:var(--color-muted-foreground);margin-bottom:12px;display:flex;align-items:center;gap:6px;flex-wrap:wrap}.status:before{content:'';width:6px;height:6px;border-radius:50%;background:var(--blue)}.status.rejected:before{background:var(--rose)}.status.pending:before{background:#c98a46}.company{font-size:12px;color:var(--color-muted-foreground);margin-bottom:5px}.summary{font-size:13px;color:var(--color-muted-foreground);margin-top:10px}.detail section{padding:16px 20px;border-bottom:1px solid var(--color-border)}.facts{display:grid;grid-template-columns:1fr 1fr;gap:14px}.facts dt{font-size:11px;color:var(--color-muted-foreground);margin-bottom:4px}.facts dd{margin:0;font-size:13px}.facts small{display:block;font-size:11px;margin-top:2px}.wide{grid-column:1/-1}.contact{display:flex;gap:10px;align-items:center;margin-top:10px}.avatar{width:30px;height:30px;border-radius:50%;background:var(--color-muted);display:grid;place-items:center;font-size:11px;color:var(--color-muted-foreground);flex-shrink:0}.contact b{font-size:13px;display:block;font-weight:550}.contact small{font-size:11px;display:block}.contact a{font-size:12px}.detail .muted,.reference{margin-top:10px;font-size:12px;color:var(--color-muted-foreground)}.prep{border-left:2px solid var(--blue);padding-left:10px;font-size:13px;margin-top:10px}.questions{padding-left:16px;margin:8px 0 0;font-size:12px;color:var(--color-muted-foreground)}.questions li{margin-top:5px}.actions{display:flex;gap:8px;flex-wrap:wrap;padding:16px 20px}.evidence{padding:0 20px 20px;font-size:12px;color:var(--color-muted-foreground)}summary{cursor:pointer}.evidence p{margin:12px 0;overflow-wrap:anywhere}.original-note,.saved-note p{white-space:pre-wrap}.attention{color:#a87039!important;font-size:12px;margin-top:8px}.empty{padding:25px 15px;color:var(--color-muted-foreground)}.note-form,.saved-note{padding:0 20px 20px}.note-form label{font-size:12px;display:block;margin-bottom:8px}textarea{display:block;width:100%;min-height:110px;padding:10px;resize:vertical;background:var(--color-muted);border:1px solid var(--color-border);border-radius:8px;color:inherit;margin-bottom:10px}.note-form .button{margin-right:5px}.saved-note p{font-size:13px;margin:8px 0;overflow-wrap:anywhere}.notice{padding:0 20px 16px;font-size:12px}.review{margin-bottom:16px}footer{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px;padding:18px 0;font-size:11px;color:var(--color-muted-foreground)}footer small{flex-basis:100%;font-size:11px}.mobile-back{display:none}.call .overview,.call .filters,.call .master,.call .controls select{display:none}.call .workspace{display:block;max-width:780px;margin:auto}.call .detail{max-height:none}.call .detail h2{font-size:26px}.call .prep{font-size:16px}.call-results{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:15px}
 @media(max-width:900px){.workspace{gap:12px;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr)}.overview{grid-template-columns:155px minmax(0,1fr)}.stats{padding:17px}.detail-head,.detail section{padding:15px}.stats-bottom{gap:20px}}
 @media(max-width:640px){.career{padding:20px 14px}.heading{align-items:flex-start}h1{font-size:25px}.heading p{max-width:190px;font-size:12px}.heading .button{padding:9px;font-size:11px}.overview{grid-template-columns:1fr}.stats{display:flex;align-items:center;gap:15px;border-right:0;border-bottom:1px solid var(--color-border);padding:15px}.stats-bottom{border:0;padding:0;margin:0 0 0 auto}.number{font-size:31px}.plot{padding:14px 14px 10px}.plot svg{height:auto}.controls{flex-wrap:wrap}.search{flex-basis:calc(100% - 60px)}.search input{font-size:16px}.controls select{flex:1}.refresh{order:0}.workspace{grid-template-columns:1fr}.list{max-height:none;overflow:visible;padding-right:0}.detail{display:none;max-height:none}.mobile-detail .detail,.call .detail{display:block}.mobile-detail .master,.mobile-detail .overview,.mobile-detail .filters{display:none}.mobile-detail .mobile-back{display:inline-flex;margin-bottom:12px}.call .detail h2{font-size:23px}.detail-head,.detail section{padding:17px}.list .row{padding:14px}.filters button{padding:7px 8px;font-size:11px}}
</style>
